import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.PlainSelect;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.statement.select.SelectBody;
import net.sf.jsqlparser.statement.select.SelectExpressionItem;
import net.sf.jsqlparser.statement.select.SelectItem;

import java.util.List;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    Statement stmt;
    try {
        stmt = CCJSqlParserUtil.parse(sql);
    } catch (JSQLParserException e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }

    if (!(stmt instanceof Select)) {
        throw new PageException("分页语句必须是Select查询!");
    }

    Select select = (Select) stmt;
    SelectBody selectBody = select.getSelectBody();

    if (selectBody instanceof PlainSelect) {
        PlainSelect plainSelect = (PlainSelect) selectBody;
        List<SelectItem> selectItems = plainSelect.getSelectItems();

        for (SelectItem selectItem : selectItems) {
            if (selectItem instanceof SelectExpressionItem) {
                SelectExpressionItem selectExpressionItem = (SelectExpressionItem) selectItem;
                String expression = selectExpressionItem.getExpression().toString();

                if (expression.contains("[START_ROW]")) {
                    expression = expression.replace("[START_ROW]", offset != null ? String.valueOf(offset) : "0");
                }

                if (expression.contains("[PAGE_SIZE]")) {
                    expression = expression.replace("[PAGE_SIZE]", limit != null ? String.valueOf(limit) : "0");
                }

                selectExpressionItem.getExpression().setExpression(expression);
            }
        }
    }

    return select.toString();
}

